  const camera = visitor ? '<g transform="translate(108 89) rotate(-10)"><rect x="-14" y="-8" width="27" height="18" rx="5" fill="#587d82"/><circle r="6" cy="1" fill="#b0d7cb"/><circle r="3" cy="1" fill="#365f6c"/></g>' : '';
  return `<svg class="creature-art" viewBox="0 0 160 140" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">${drawing}${camera}</svg>`;
